package com.example.demo.adapters.jdbc;

import com.example.demo.application.commands.OpenTicketCommand;
import com.example.demo.domain.Ticket;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public class JdbcOpenTicketCommand implements OpenTicketCommand {

    private final JdbcClient jdbc;

    public JdbcOpenTicketCommand(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public Ticket execute(OpenTicketCommand.Input input) {
        JdbcClient.StatementSpec statement = jdbc.sql("insert into tickets (subject) values (:subject) returning id, subject");
        statement = statement.param("subject", input.subject());
        return statement.query(Ticket.class).single();
    }
}
